<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Accessor\SnippetEnabledAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SnippetEnabledAccessor trait.
 *
 * Covers null default, string/VO assignment via withEnabled,
 * getEnabled/enabled accessors, and isEnabledChanged with/without original.
 */
class SnippetEnabledAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withEnabled creates a new instance with the Enabled set
     * from a string value, and getEnabled returns the primitive string.
     */
    public function testWithEnabledFromString(): void
    {
        // Arrange
        $holder = new ImplWithSnippetEnabledAccessorUnitTest();

        // Act
        $result = $holder->withEnabled(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isEnabled());
    }
    /**
     * Asserts that withenabled has access to the value object
     * from a string value, and getEnabled returns the primitive string.
     */
    public function testWithEnabledFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSnippetEnabledAccessorUnitTest();

        // Act
        $result = $holder->withEnabled(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->enabled()->value());
    }
    public function testChangedEnabled(): void
    {
        // Arrange
        $holder = new ImplWithSnippetEnabledAccessorUnitTest();
        $original = $holder->withEnabled(true);
        $same = $holder->withEnabled(true);
        $modified = $holder->withEnabled(false);

        // Act
        $unchanged = $holder->isEnabledChanged();
        $withSame = $original->isEnabledChanged($same);
        $withDiferent = $original->isEnabledChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSnippetEnabledAccessorUnitTest
{
    use SnippetEnabledAccessor;
}
